const fs = require('fs');
const readline = require('readline');

async function main() {
  const fileStream = fs.createReadStream('C:\\Users\\Satish kumar\\.gemini\\antigravity-ide\\brain\\c7d33e12-1c9e-4431-afaa-d6a0af26bc2c\\.system_generated\\logs\\transcript_full.jsonl');
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const obj = JSON.parse(line);
      const str = JSON.stringify(obj);
      if (str.includes('density-compact') || str.includes('--mc-radius-2xs')) {
        console.log(`Step ${obj.step_index} (${obj.type}, ${obj.source}) has match: length=${str.length}`);
        fs.writeFileSync(`scratch_match_${obj.step_index}.json`, str);
      }
    } catch (e) {}
  }
}

main();
